require_once 'config/config.php';$id=(int)($_GET['id']??0);$in=$_GET['check_in']??date('Y-m-d',strtotime('+1 day'));$out=$_GET['check_out']??date('Y-m-d',strtotime('+2 day'));$guests=max(1,(int)($_GET['guests']??1));
$s=db()->prepare("SELECT r.*,rt.name type_name,rt.description,rt.capacity,rt.amenities FROM rooms r JOIN room_types rt ON rt.id=r.room_type_id WHERE r.id=?");$s->execute([$id]);$room=$s->fetch();if(!$room)exit('Room not found');$n=nights($in,$out);$total=$n*(float)$room['price'];$title=$room['type_name'].' | '.APP_NAME;
require 'partials_header.php'; ?>
<div class="page"><div class="container"><div class="room-layout"><img src="<?=e($room['image'])?>" alt="<?=e($room['type_name'])?>"><div class="panel"><h1><?=e($room['type_name'])?></h1><p><?=e($room['description'])?></p><div class="chips"><?php foreach(explode(',',$room['amenities']) as $a): ?><span class="chip"><?=e(trim($a))?></span><?php endforeach;?></div><h3>Room <?=e($room['room_number'])?></h3><div class="price">NPR <?=number_format((float)$room['price'])?> / night</div><hr>
<form action="book.php" method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="room_id" value="<?=$id?>"><input type="hidden" name="check_in" value="<?=e($in)?>"><input type="hidden" name="check_out" value="<?=e($out)?>"><input type="hidden" name="guests" value="<?=$guests?>"><p><label>Special request</label><textarea name="special_request" placeholder="Optional"></textarea></p><p><strong><?=$n?> night(s) · Total NPR <?=number_format($total)?></strong></p><button class="btn orange" style="width:100%">Reserve & Continue</button></form></div></div></div></div><?php require 'partials_footer.php'; ?>
